CREATE FUNCTION public.admin_approve_documents(request_id uuid,review_note text,reviewed_fee integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE original public.license_requests;BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden';END IF;IF length(trim(review_note))=0 OR length(review_note)>2000 THEN RAISE EXCEPTION 'Invalid review';END IF;SELECT * INTO original FROM public.license_requests WHERE id=request_id AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR original.status<>'awaiting_document_review' THEN RAISE EXCEPTION 'Request is not awaiting document review';END IF;IF reviewed_fee IS NOT NULL AND(original.kind='new' OR reviewed_fee<=0 OR reviewed_fee>1000000) THEN RAISE EXCEPTION 'Invalid reviewed fee';END IF;IF coalesce(reviewed_fee,original.fee) IS NULL THEN RAISE EXCEPTION 'Fee required before payment';END IF;UPDATE public.license_requests SET fee=coalesce(reviewed_fee,fee),documents_approved_at=now(),status='awaiting_payment' WHERE id=request_id;INSERT INTO public.admin_request_events(request_id,actor_id,action,note) VALUES(request_id,auth.uid(),'documents_approved',review_note);END $$;
CREATE FUNCTION public.submit_payment_receipt(request_id uuid,receipt_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized';END IF;IF receipt_path NOT LIKE auth.uid()::text||'/'||request_id::text||'/receipt-%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='license-documents' AND name=receipt_path) THEN RAISE EXCEPTION 'Receipt file missing';END IF;UPDATE public.license_requests SET receipt_path=submit_payment_receipt.receipt_path,receipt_uploaded_at=now(),status='awaiting_payment_review' WHERE id=request_id AND user_id=auth.uid() AND deleted_at IS NULL AND status='awaiting_payment';IF NOT FOUND THEN RAISE EXCEPTION 'Payment is not open for this request';END IF;END $$;
CREATE FUNCTION public.admin_confirm_treasury_payment(request_id uuid,receipt_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden';END IF;IF length(trim(receipt_reference))<3 OR length(receipt_reference)>200 THEN RAISE EXCEPTION 'Receipt reference required';END IF;UPDATE public.license_requests SET paid_at=now(),status='under_review' WHERE id=request_id AND deleted_at IS NULL AND paid_at IS NULL AND fee>0 AND status IN('awaiting_payment','awaiting_payment_review');IF NOT FOUND THEN RAISE EXCEPTION 'Payment cannot be confirmed';END IF;INSERT INTO public.admin_request_events(request_id,actor_id,action,note) VALUES(request_id,auth.uid(),'treasury_payment_confirmed',receipt_reference);END $$;
CREATE FUNCTION public.admin_review_request(request_id uuid,next_status text,review_note text,reviewed_fee integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE original public.license_requests;BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden';END IF;IF next_status NOT IN('under_review','issued','rejected') OR length(trim(review_note))=0 OR length(review_note)>2000 THEN RAISE EXCEPTION 'Invalid review';END IF;SELECT * INTO original FROM public.license_requests WHERE id=request_id AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable';END IF;IF original.status='issued' THEN RAISE EXCEPTION 'Issued license cannot be reissued';END IF;IF next_status IN('under_review','issued') AND original.paid_at IS NULL THEN RAISE EXCEPTION 'Confirmed payment required';END IF;IF reviewed_fee IS NOT NULL AND(original.kind='new' OR reviewed_fee<=0 OR reviewed_fee>1000000) THEN RAISE EXCEPTION 'Invalid reviewed fee';END IF;UPDATE public.license_requests SET status=next_status,fee=coalesce(reviewed_fee,fee),issued_at=CASE WHEN next_status='issued' THEN now() ELSE issued_at END,expires_at=CASE WHEN next_status='issued' THEN now()+interval '1 year' ELSE expires_at END WHERE id=request_id;INSERT INTO public.admin_request_events(request_id,actor_id,action,note) VALUES(request_id,auth.uid(),next_status,review_note);END $$;
REVOKE ALL ON FUNCTION public.admin_approve_documents(uuid,text,integer),public.submit_payment_receipt(uuid,text),public.admin_confirm_treasury_payment(uuid,text),public.admin_review_request(uuid,text,text,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.admin_approve_documents(uuid,text,integer),public.submit_payment_receipt(uuid,text),public.admin_confirm_treasury_payment(uuid,text),public.admin_review_request(uuid,text,text,integer) TO authenticated;
CREATE FUNCTION public.capture_document_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.required_document_snapshot IS DISTINCT FROM OLD.required_document_snapshot OR NEW.activity_category IS DISTINCT FROM OLD.activity_category THEN RAISE EXCEPTION 'Requirement snapshot is read-only';END IF;RETURN NEW;END IF;NEW.required_document_snapshot:=(SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',d.name) ORDER BY d.id),'[]') FROM public.documents d JOIN jsonb_array_elements(NEW.documents) a ON(a->>'slot')::integer=d.id);RETURN NEW;END $$;CREATE TRIGGER capture_document_snapshot BEFORE INSERT OR UPDATE ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.capture_document_snapshot();
CREATE FUNCTION public.snapshot_application_documents() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.application_documents(request_id,document_id,document_name,path,bucket) SELECT NEW.id,(s->>'id')::integer,s->>'name',d->>'path',coalesce(d->>'bucket','license-documents') FROM jsonb_array_elements(NEW.required_document_snapshot)s JOIN jsonb_array_elements(NEW.documents)d ON d->>'slot'=s->>'id';RETURN NEW;END $$;CREATE TRIGGER snapshot_application_documents AFTER INSERT ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.snapshot_application_documents();
CREATE FUNCTION public.notify_portal_account_created() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.account_notifications(user_id,title,message) VALUES(NEW.id,'أهلًا بك في بوابة التراخيص','تم إنشاء حسابك. يمكنك اختيار الخدمة من الصفحة الرئيسية.');RETURN NEW;END $$;CREATE TRIGGER notify_portal_profile_created AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.notify_portal_account_created();
CREATE FUNCTION public.notify_license_request_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE title_text text;message_text text;BEGIN IF TG_OP='INSERT' THEN title_text:='تم رفع جميع المستندات';message_text:='طلبك '||NEW.temp_track_id||' في انتظار مراجعة الإدارة للأوراق خلال 48 ساعة.';ELSIF NEW.status IS DISTINCT FROM OLD.status THEN title_text:='تحديث على طلبك';message_text:=NEW.temp_track_id||' — '||CASE NEW.status WHEN 'awaiting_payment' THEN 'تمت الموافقة على مستنداتك. يمكنك الآن الدفع ورفع صورة الإيصال من صفحة طلباتي. الرسوم: '||coalesce(NEW.fee::text,'')||' جنيه مصري.' WHEN 'awaiting_payment_review' THEN 'تم استلام إيصال الدفع.' WHEN 'under_review' THEN 'تم تأكيد السداد؛ طلبك قيد المراجعة النهائية.' WHEN 'issued' THEN 'تم إصدار الترخيص.' WHEN 'rejected' THEN 'تم رفض الطلب. راجع ملاحظات الإدارة.' ELSE NEW.status END;ELSE RETURN NEW;END IF;INSERT INTO public.account_notifications(user_id,request_id,title,message) VALUES(NEW.user_id,NEW.id,title_text,message_text);RETURN NEW;END $$;CREATE TRIGGER notify_license_request_changes AFTER INSERT OR UPDATE ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.notify_license_request_event();
REVOKE ALL ON FUNCTION public.notify_portal_account_created(),public.notify_license_request_event() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.send_license_renewal_alerts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inserted_count integer;BEGIN INSERT INTO public.account_notifications(user_id,request_id,title,message,event_key) SELECT r.user_id,r.id,CASE WHEN r.expires_at<=now() THEN 'انتهت صلاحية الترخيص' ELSE 'تذكير بتجديد الترخيص' END,'يمكنك تجديد الترخيص '||r.temp_track_id||' من حسابك.','renewal:'||r.id::text||':'||r.expires_at::text||':'||CASE WHEN r.expires_at<=now() THEN 'expired' ELSE '30days' END FROM public.license_requests r WHERE r.status='issued' AND r.deleted_at IS NULL AND r.expires_at IS NOT NULL AND r.expires_at<=now()+interval '30 days' AND NOT EXISTS(SELECT 1 FROM public.license_requests n WHERE n.parent_id=r.id AND n.kind='renewal' AND n.status='issued' AND n.deleted_at IS NULL AND n.expires_at>r.expires_at) ON CONFLICT(event_key) WHERE event_key IS NOT NULL DO NOTHING;GET DIAGNOSTICS inserted_count=ROW_COUNT;RETURN inserted_count;END $$;REVOKE ALL ON FUNCTION public.send_license_renewal_alerts() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.send_license_renewal_alerts() TO service_role;
CREATE FUNCTION public.request_missing_documents(p_request uuid,p_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR length(trim(p_note))=0 OR length(p_note)>2000 THEN RAISE EXCEPTION 'Forbidden';END IF;UPDATE public.license_requests SET status='needs_info' WHERE id=p_request AND status='awaiting_document_review' AND deleted_at IS NULL;IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable';END IF;INSERT INTO public.admin_request_events(request_id,actor_id,action,note) VALUES(p_request,auth.uid(),'needs_info',p_note);END $$;
CREATE FUNCTION public.submit_missing_document(p_request uuid,p_slot integer,p_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.license_requests;BEGIN SELECT * INTO r FROM public.license_requests WHERE id=p_request AND user_id=auth.uid() AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR r.status<>'needs_info' THEN RAISE EXCEPTION 'Request unavailable';END IF;IF p_path NOT LIKE auth.uid()::text||'/'||p_request::text||'/supplements/%/'||p_slot::text||'.pdf' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='license-documents' AND name=p_path AND metadata->>'mimetype'='application/pdf') THEN RAISE EXCEPTION 'Stored owner PDF required';END IF;UPDATE public.application_documents SET path=p_path,bucket='license-documents' WHERE request_id=p_request AND document_id=p_slot;IF NOT FOUND THEN RAISE EXCEPTION 'Document not in snapshot';END IF;UPDATE public.license_requests SET documents=(SELECT jsonb_agg(CASE WHEN(d->>'slot')::integer=p_slot THEN d||jsonb_build_object('path',p_path,'bucket','license-documents') ELSE d END) FROM jsonb_array_elements(r.documents)d) WHERE id=p_request;INSERT INTO public.admin_request_events(request_id,actor_id,action,note) VALUES(p_request,auth.uid(),'document_uploaded','تم رفع المستند '||p_slot);END $$;
CREATE FUNCTION public.resubmit_missing_documents(p_request uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.license_requests SET status='awaiting_document_review' WHERE id=p_request AND user_id=auth.uid() AND status='needs_info' AND deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.admin_request_events e WHERE e.request_id=p_request AND e.action='document_uploaded' AND e.created_at>(SELECT max(created_at) FROM public.admin_request_events WHERE request_id=p_request AND action='needs_info'));IF NOT FOUND THEN RAISE EXCEPTION 'Upload missing documents first';END IF;INSERT INTO public.admin_request_events(request_id,actor_id,action,note) VALUES(p_request,auth.uid(),'awaiting_document_review','تم استكمال المستندات وإعادة الطلب للمراجعة');END $$;
REVOKE ALL ON FUNCTION public.request_missing_documents(uuid,text),public.submit_missing_document(uuid,integer,text),public.resubmit_missing_documents(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.request_missing_documents(uuid,text),public.submit_missing_document(uuid,integer,text),public.resubmit_missing_documents(uuid) TO authenticated;